		if p.NotFixedYet {
			pkgs[n] = p
			continue
		}

		// OVALv1 includes definitions other than the target RHEL version
		if !strings.Contains(p.Version, ".el"+v) && !strings.Contains(p.Version, ".module+el"+v) {
